    let multi: [i128; 7] = [86_400_000_000, 1_000_000, 1, 1000, 60_000_000, 3_600_000_000, 604_800_000_000];
    let mut us: i128 = 0;
    let mut acc: Option<Big> = None;
    let mut left: f64 = 0.0;
    for (k, n) in names.iter().enumerate() {
