            Some(V::Int(i)) => td_add_int(&mut us, &mut acc, i as i128 * multi[k]),
            Some(V::Bool(b)) => td_add_int(&mut us, &mut acc, b as i128 * multi[k]),
            Some(V::Big(x)) => td_add_big(&mut us, &mut acc, &x.mul(&Big::from_i128(multi[k]))),
